<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\Review;
use App\Domain\Review\Entity\Flashcard;use App\Domain\Review\Enum\FlashcardSource;use App\Domain\Review\Enum\FlashcardType;use App\Domain\Review\Repository\FlashcardRepositoryInterface;use App\Domain\Review\ValueObject\FlashcardFingerprint;use App\Infrastructure\Persistence\Doctrine\Review\Entity\FlashcardRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineFlashcardRepository implements FlashcardRepositoryInterface { public function __construct(private readonly EntityManagerInterface $em){} public function findByFingerprint(string $subject,FlashcardFingerprint $fingerprint):?Flashcard{$r=$this->em->getRepository(FlashcardRecord::class)->findOneBy(['primaryTaxonomySubjectId'=>$subject,'fingerprintVersion'=>$fingerprint->version,'fingerprint'=>$fingerprint->value]);return $r instanceof FlashcardRecord?$this->map($r):null;} public function findById(string $id):?Flashcard{$r=$this->em->find(FlashcardRecord::class,$id);return $r instanceof FlashcardRecord?$this->map($r):null;} public function save(Flashcard $c):void{$r=$this->em->find(FlashcardRecord::class,$c->id)??new FlashcardRecord();$r->id=$c->id;$r->primaryTaxonomySubjectId=$c->primaryTaxonomySubjectId;$r->type=$c->type->value;$r->front=$c->front;$r->back=$c->back;$r->fingerprintVersion=$c->fingerprint->version;$r->fingerprint=$c->fingerprint->value;$r->source=$c->source->value;$r->createdAt=$c->createdAt;$r->updatedAt=$c->updatedAt;$this->em->persist($r);} private function map(FlashcardRecord $r):Flashcard{return new Flashcard($r->id,$r->primaryTaxonomySubjectId,FlashcardType::from($r->type),$r->front,$r->back,new FlashcardFingerprint($r->fingerprintVersion,$r->fingerprint),FlashcardSource::from($r->source),$r->createdAt,$r->updatedAt);} }
